// Example: Basic Vue component setup
import { createApp } from 'vue';

export default {
  props: {
    // props will be defined here
  },
  setup() {
    return {};
  }
};

// Example: defining a prop with specific string values
defineProps({
  status: {
    type: String,
    required: true,
    validator: (value) => ['active', 'inactive'].includes(value)
  }
})

// Adding a prop conditionally required
defineProps({
  variant: {
    type: String,
    required: true,
    validator: (value) => ['primary', 'secondary'].includes(value)
  },
  label: {
    type: String,
    required: true
  }
})

// Adding another prop variant
defineProps({
  variant: {
    type: String,
    required: true,
    validator: (value) => ['primary', 'secondary', 'danger'].includes(value)
  },
  errorMessage: {
    type: String,
    required: true
  }
})

// Adding a third variant to props
defineProps({
  type: {
    type: String,
    required: true,
    validator: (value) => ['text', 'number', 'loading'].includes(value)
  },
  loading: {
    type: Boolean
  }
})
